function MonteCarloMeans(n, p, T):
    sum_edges, sum_iso, sum_tri <- 0, 0, 0
    repeat T times:
        E <- {}
        for each pair {i, j} with i < j:
            if Uniform(0,1) < p: add {i,j} to E
        sum_edges <- sum_edges + |E|
        sum_iso   <- sum_iso + (n - |vertices touched by E|)
        sum_tri   <- sum_tri + #{triples {a,b,c} all-adjacent in E}
    return (sum_edges/T, sum_iso/T, sum_tri/T)

